// Тикет #6a86f7fd · 6a86f7fd7a0ea006134e7fe1 F-36 «פיתוח: תלות חיצונית במסירת תזכורות והתראות» — принят 13.10.2026 (iPhone, TestFlight 1.0.0 (19)).
// Кейс .qa/tests/profile/PR-05-system-reminders-switch.md. Факты 13.10: label тумблера, «תזכורות במערכת: השינוי נשמר.»,
// под тумблером нет «אישור התראות במכשיר עדיין אינו זמין»; при запрете уведомлений в iOS — кнопка «פתיחת הגדרות המכשיר».
// @data: тумблер переключается дважды — исходное состояние возвращается (и в finally, если тест упал посередине).
import { expect, driver } from '@wdio/globals';
import { byText, byTextContains } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { skipWith } from '../_lib/app-0710.ts';
import {
  appId, openProfileReminders, sysRemindersOn, sysRemindersLabel, toggleSysReminders,
  SYS_REMINDERS_LABEL, OLD_NOT_AVAILABLE, OPEN_DEVICE_SETTINGS,
} from '../_lib/app-1310b.ts';

describe('Профиль — «תזכורות והתראות» (F-36)', () => {
  afterEach(async () => { await toHome(); });

  it('PR-05 Тумблер «תזכורות והתראות»: label, «השינוי נשמר.», нет «…עדיין אינו זמין», состояние возвращено #6a86f7fd @data', async () => {
    await openProfileReminders();
    const initial = await sysRemindersOn();
    try {
      // 1. Label тумблера — полный текст F-36; старого текста под тумблером нет.
      expect(await sysRemindersLabel()).toBe(SYS_REMINDERS_LABEL);
      await expect(byTextContains(OLD_NOT_AVAILABLE)).not.toBeDisplayed();

      // 2. Переключить → «תזכורות במערכת: השינוי נשמר.», состояние сменилось; старого текста нет.
      expect(await toggleSysReminders()).toBe(!initial);
      await expect(byTextContains(OLD_NOT_AVAILABLE)).not.toBeDisplayed();

      // 3. Перезаход в профиль — новое состояние сохранено.
      await openProfileReminders();
      expect(await sysRemindersOn()).toBe(!initial);

      // 4. Вернуть исходное → снова «השינוי נשמר.».
      expect(await toggleSysReminders()).toBe(initial);
      await expect(byTextContains(OLD_NOT_AVAILABLE)).not.toBeDisplayed();
    } finally {
      await openProfileReminders();
      if ((await sysRemindersOn()) !== initial) await toggleSysReminders();
      expect(await sysRemindersOn()).toBe(initial);
    }
  });

  it('PR-05b Уведомления запрещены в настройках ОС → под тумблером «פתיחת הגדרות המכשיר», открывает Настройки #6a86f7fd @prod-safe @manual-check', async function () {
    // Подготовка руками: iOS «Настройки → אור הגאולה → Уведомления» = выкл (Android — «Уведомления приложения» выкл), затем QA_NOTIF_DENIED=1.
    if (process.env.QA_NOTIF_DENIED !== '1') {
      skipWith(this, 'нужно запретить уведомления приложения в настройках ОС и задать QA_NOTIF_DENIED=1 (после теста — включить обратно)');
    }
    await openProfileReminders();
    await expect(byText(OPEN_DEVICE_SETTINGS)).toBeDisplayed({ wait: 10000 });
    await expect(byTextContains(OLD_NOT_AVAILABLE)).not.toBeDisplayed();
    await (await byText(OPEN_DEVICE_SETTINGS)).click();
    // Открылись настройки ОС (iOS — com.apple.Preferences; Android — Settings). Вернуться в приложение.
    await driver.waitUntil(async () => (await driver.queryAppState(appId())) < 4, { timeout: 10000, timeoutMsg: '«פתיחת הגדרות המכשיר» не открыла настройки устройства' });
    await driver.activateApp(appId());
    await (await byText('פרופיל אישי')).waitForDisplayed({ timeout: 20000 }).catch(() => {});
  });
});
